<?php
require '_init.php';$pageTitle='Manage Reservations';$allowed=['Pending','Confirmed','Cancelled','Completed'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$status=$_POST['status']??'';if(in_array($status,$allowed,true)){$s=$pdo->prepare("UPDATE reservations SET status=? WHERE id=?");$s->execute([$status,(int)$_POST['id']]);set_flash('Reservation updated.');}redirect('reservations.php');}
$rows=$pdo->query("SELECT * FROM reservations ORDER BY reservation_date DESC,reservation_time DESC")->fetchAll();require '../includes/header.php';
?>
<section class="page-heading"><span class="eyebrow">ADMIN</span><h1>Table Reservations</h1></section><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Contact</th><th>Date & time</th><th>Guests</th><th>Notes</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['customer_name']) ?></td><td><?= e($r['email']) ?><br><?= e($r['phone']) ?></td><td><?= e($r['reservation_date']) ?><br><?= e(substr($r['reservation_time'],0,5)) ?></td><td><?= (int)$r['guests'] ?></td><td><?= e($r['notes']) ?></td><td><?= e($r['status']) ?></td><td><form method="post" class="status-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><select name="status"><?php foreach($allowed as $a): ?><option <?= $r['status']===$a?'selected':'' ?>><?= e($a) ?></option><?php endforeach; ?></select><button class="small-btn">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div>
<?php require '../includes/footer.php'; ?>
